import { GoogleGenAI } from "@google/genai";

export const analyzeClinicData = async (prompt: string, dataContext: any) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const systemInstruction = `
    You are a Senior Strategic Advisor for a Medical Clinic. 
    You have access to patient CRM data, inventory levels, and financial reports.
    Your task is to provide high-level business intelligence, detect trends, and suggest optimizations.

    Format: Use Markdown for headers, bullet points, and bold text.
    Constraint: Focus on Net Profit logic (Revenue - Consumables - Commissions).
  `;

  const contextStr = JSON.stringify(dataContext);
  const fullPrompt = `Data Context: ${contextStr}\n\nUser Question: ${prompt}`;

  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: fullPrompt,
    config: {
      systemInstruction,
      thinkingConfig: { thinkingBudget: 32768 }
    },
  });

  return response.text;
};

import React, { useState } from 'react';
import { analyzeClinicData } from '../services/gemini';

const ClinicAI: React.FC = () => {
  const [query, setQuery] = useState('');
  const [response, setResponse] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  // Simulated data to feed as context to the AI
  const mockContext = {
    inventory: [
      { name: 'Needles 1cc', stock: 15, limit: 20 },
      { name: 'Botox Vial', stock: 5, limit: 10 }
    ],
    last_week_profit: 4200,
    top_service: 'Dental Implant',
    patient_satisfaction: '4.8/5'
  };

  const handleAsk = async () => {
    if (!query) return;
    setIsLoading(true);
    setResponse('');
    try {
      const result = await analyzeClinicData(query, mockContext);
      setResponse(result || 'No response generated.');
    } catch (error) {
      setResponse(`Error: ${error instanceof Error ? error.message : 'Unknown error'}`);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      <div className="bg-indigo-900 rounded-3xl p-10 text-white shadow-2xl relative overflow-hidden">
        <div className="relative z-10">
