const N8N_WEBHOOK_URL = 'https://your-n8n-instance.com/webhook/clinic-events';

export const triggerN8nEvent = async (eventType: 'LOW_STOCK' | 'REMINDER' | 'HIGH_VALUE_INVOICE', payload: any) => {
  try {
    const response = await fetch(N8N_WEBHOOK_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        event: eventType,
        timestamp: new Date().toISOString(),
        data: payload
      })
    });
    return response.ok;
  } catch (error) {
    console.error('n8n Webhook Error:', error);
    return false;
  }
};

