import { Patient } from '../types';

// Extended Patient interface for local UI state to include photos
interface PatientWithPhotos extends Patient {
  photos?: { id: string; url: string; type: 'BEFORE' | 'AFTER'; date: string }[];
}

const INITIAL_PATIENTS: PatientWithPhotos[] = [
  { 
    id: '1', 
    name: 'أليس فريمان', 
    age: 29, 
    phones: ['+1 234 567 890'], 
    medical_history: ['حساسية اللاتكس', 'وردية'], 
    address: 'شارع 1، المدينة', 
    created_at: '2023-11-15',
    photos: [
      { id: 'p1', url: 'https://picsum.photos/400/300?grayscale&u=1', type: 'BEFORE', date: '2023-11-15' },
      { id: 'p2', url: 'https://picsum.photos/400/300?u=1', type: 'AFTER', date: '2023-12-10' }
    ]
  },
  { id: '2', name: 'روبرت تشن', age: 45, phones: ['+1 345 678 901', '+1 987 654 321'], medical_history: ['السكري النوع الثاني'], address: 'شارع 5، المنطقة الصناعية', created_at: '2023-12-01', photos: [] },
  { id: '3', name: 'زوي كرافيتز', age: 34, phones: ['+1 567 890 123'], medical_history: ['ضغط الدم'], address: 'بناية الياسمين، الطابق 3', created_at: '2023-12-10', photos: [] },
];

const PatientCRM: React.FC = () => {
  const [patients, setPatients] = useState<PatientWithPhotos[]>(INITIAL_PATIENTS);
  const [selectedPatient, setSelectedPatient] = useState<PatientWithPhotos | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [modalMode, setModalMode] = useState<'ADD' | 'EDIT' | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Modal Form State
  const [formData, setFormData] = useState({
    name: '',
    age: '',
    phone1: '',
    phone2: '',
    address: '',
    medical: ''
  });

  // Filter logic
  const filteredPatients = useMemo(() => {
    return patients.filter(p => 
      p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      p.phones.some(phone => phone.includes(searchQuery))
    );
  }, [patients, searchQuery]);

  const openAddModal = () => {
    setModalMode('ADD');
    setFormData({ name: '', age: '', phone1: '', phone2: '', address: '', medical: '' });
  };

  const openEditModal = (patient: PatientWithPhotos) => {
    setModalMode('EDIT');
    setFormData({
      name: patient.name,
      age: patient.age.toString(),
      phone1: patient.phones[0] || '',
      phone2: patient.phones[1] || '',
      address: patient.address,
      medical: patient.medical_history.join(', ')
    });
  };

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const phones = [formData.phone1, formData.phone2].filter(p => p.trim() !== '');
    const medical = formData.medical.split(',').map(s => s.trim()).filter(s => s !== '');

    if (modalMode === 'ADD') {
      const newPatient: PatientWithPhotos = {
        id: (patients.length + 1).toString(),
        name: formData.name,
        age: parseInt(formData.age) || 0,
        phones: phones,
        address: formData.address,
        medical_history: medical,
        created_at: new Date().toISOString().split('T')[0],
        photos: []
      };
      setPatients([newPatient, ...patients]);
      setSelectedPatient(newPatient);
    } else if (modalMode === 'EDIT' && selectedPatient) {
      const updatedPatients = patients.map(p => 
        p.id === selectedPatient.id 
        ? { ...p, name: formData.name, age: parseInt(formData.age) || 0, phones: phones, address: formData.address, medical_history: medical }
        : p
      );
      setPatients(updatedPatients);
      setSelectedPatient(updatedPatients.find(p => p.id === selectedPatient.id) || null);
    }

    setModalMode(null);
  };

  const handleAddPhoto = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!selectedPatient || !e.target.files?.length) return;

    // Simulate photo upload
    const file = e.target.files[0];
    const reader = new FileReader();
    reader.onload = (event) => {
      const newPhoto = {
        id: Math.random().toString(36).substr(2, 9),
        url: event.target?.result as string,
        type: (selectedPatient.photos?.length || 0) % 2 === 0 ? 'BEFORE' : 'AFTER' as any,
        date: new Date().toISOString().split('T')[0]
      };

      const updatedPatients = patients.map(p => 
        p.id === selectedPatient.id 
        ? { ...p, photos: [...(p.photos || []), newPhoto] }
        : p
      );
      setPatients(updatedPatients);
      setSelectedPatient(updatedPatients.find(p => p.id === selectedPatient.id) || null);
    };
    reader.readAsDataURL(file);
  };

  const closeDetails = () => setSelectedPatient(null);

  return (
    <div className="h-full flex flex-col gap-4 lg:gap-6 text-right">
      <div className="flex items-center justify-between">
