                    <p className="text-slate-500 font-medium">{selectedPatient.age} سنة • معرف: {selectedPatient.id}</p>
                    <div className="mt-3 flex flex-wrap gap-2">
                      {selectedPatient.medical_history.length > 0 ? selectedPatient.medical_history.map((m, i) => (
                        <span key={i} className="px-3 py-1 bg-red-50 text-red-600 text-xs font-bold rounded-lg border border-red-100">
