                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                    إضافة صور
                  </button>
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    accept="image/*" 
                    onChange={handleAddPhoto} 
                  />
                </div>

                {selectedPatient.photos && selectedPatient.photos.length > 0 ? (
                  <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                    {selectedPatient.photos.map((photo) => (
                      <div key={photo.id} className="relative group rounded-2xl overflow-hidden border border-slate-200 aspect-[4/3] bg-slate-50 shadow-sm">
                        <img src={photo.url} alt={photo.type} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                        <div className={`absolute top-2 right-2 px-2 py-0.5 rounded text-[10px] font-bold uppercase shadow-sm text-white ${photo.type === 'BEFORE' ? 'bg-black/60' : 'bg-emerald-500'}`}>
                          {photo.type === 'BEFORE' ? 'قبل' : 'بعد'}
                        </div>
                        <div className="absolute bottom-0 inset-x-0 p-2 bg-gradient-to-t from-black/50 to-transparent opacity-0 group-hover:opacity-100 transition-opacity">
                          <p className="text-[9px] text-white font-medium">{photo.date}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="p-10 border-2 border-dashed border-slate-100 rounded-2xl flex flex-col items-center justify-center text-slate-300">
                    <svg className="w-10 h-10 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                    <p className="text-xs font-bold">لا يوجد صور مؤرشفة حالياً</p>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="bg-white/50 border-2 border-dashed border-slate-200 rounded-2xl h-full flex flex-col items-center justify-center text-slate-400 text-center px-4 space-y-4">
              <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center">
                <svg className="w-8 h-8 text-slate-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
              </div>
              <p className="text-sm font-medium">اختر مريضاً من القائمة لعرض تفاصيل ملفه الطبي</p>
            </div>
          )}
        </div>
      </div>

      {/* Unified Add/Edit Patient Modal */}
      {modalMode && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-6 lg:p-8 max-w-lg w-full shadow-2xl animate-in zoom-in-95 duration-200 text-right">
            <h2 className="text-xl font-bold mb-6 text-slate-800 flex items-center gap-2">
              <span className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white text-lg">
                {modalMode === 'ADD' ? '+' : '✎'}
              </span>
              {modalMode === 'ADD' ? 'تسجيل مريض جديد' : 'تعديل بيانات المريض'}
            </h2>
            <form onSubmit={handleFormSubmit} className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="sm:col-span-2">
                <label className="block text-xs font-bold text-slate-500 mb-1">الاسم الكامل</label>
                <input 
                  type="text" required value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                  className="w-full px-4 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 mb-1">العمر</label>
                <input 
                  type="number" required value={formData.age}
                  onChange={(e) => setFormData({...formData, age: e.target.value})}
                  className="w-full px-4 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 mb-1">الهاتف الأساسي</label>
                <input 
                  type="text" required dir="ltr" value={formData.phone1}
                  onChange={(e) => setFormData({...formData, phone1: e.target.value})}
                  className="w-full px-4 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                />
              </div>
              <div className="sm:col-span-2">
                <label className="block text-xs font-bold text-slate-500 mb-1">العنوان</label>
                <input 
                  type="text" value={formData.address}
                  onChange={(e) => setFormData({...formData, address: e.target.value})}
                  className="w-full px-4 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                />
              </div>
              <div className="sm:col-span-2">
                <label className="block text-xs font-bold text-slate-500 mb-1">السجل المرضي (افصل بينها بفاصلة)</label>
                <textarea 
                  rows={2} value={formData.medical}
                  onChange={(e) => setFormData({...formData, medical: e.target.value})}
                  placeholder="مثال: سكري، ضغط، حساسية ليدوكائين"
                  className="w-full px-4 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                />
              </div>
              <div className="sm:col-span-2 pt-4 flex gap-3">
                <button 
                  type="submit"
                  className="flex-2 bg-indigo-600 text-white py-3 px-6 rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
                >
                  {modalMode === 'ADD' ? 'حفظ البيانات' : 'تحديث البيانات'}
                </button>
                <button 
                  type="button"
                  onClick={() => setModalMode(null)}
                  className="flex-1 bg-slate-100 text-slate-600 py-3 rounded-xl font-bold hover:bg-slate-200 transition-colors"
                >
                  إلغاء
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default PatientCRM;

import React, { useState, useMemo } from 'react';
import { Material, MaterialType } from '../types';

const INITIAL_INVENTORY: Material[] = [
  { id: '1', name: 'حقن فيلر (شفايف)', type: MaterialType.SERVICE, selling_price: 350, cost_price: 120, stock_quantity: 0, order_limit: 0, unit: 'جلسة' },
  { id: '2', name: 'إبر 1سم', type: MaterialType.CONSUMABLE, selling_price: undefined, cost_price: 1.25, stock_quantity: 15, order_limit: 20, unit: 'قطعة' },
  { id: '3', name: 'حشوة أسنان ضوئية', type: MaterialType.CONSUMABLE, selling_price: undefined, cost_price: 45, stock_quantity: 42, order_limit: 10, unit: 'أنبوب' },
  { id: '4', name: 'جلسة تبييض', type: MaterialType.SERVICE, selling_price: 150, cost_price: 40, stock_quantity: 0, order_limit: 0, unit: 'جلسة' },
];

const Inventory: React.FC = () => {
  const [materials, setMaterials] = useState<Material[]>(INITIAL_INVENTORY);
  const [filter, setFilter] = useState<'ALL' | MaterialType>('ALL');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    type: MaterialType.SERVICE,
    selling_price: '',
    cost_price: '',
    stock_quantity: '',
    order_limit: '',
    unit: 'جلسة'
  });

  const filteredItems = useMemo(() => {
    return filter === 'ALL' 
      ? materials 
      : materials.filter(item => item.type === filter);
  }, [materials, filter]);

  const handleExport = () => {
    const headers = ['ID', 'Name', 'Type', 'Selling Price', 'Cost Price', 'Stock', 'Unit'];
    const rows = filteredItems.map(item => [
      item.id,
      item.name,
      item.type,
      item.selling_price || 'N/A',
      item.cost_price,
      item.stock_quantity,
      item.unit
    ]);

    const csvContent = "data:text/csv;charset=utf-8," 
      + [headers, ...rows].map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `inventory_export_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleAddMaterial = (e: React.FormEvent) => {
    e.preventDefault();
    const newMaterial: Material = {
      id: (materials.length + 1).toString(),
      name: formData.name,
      type: formData.type,
      selling_price: formData.type === MaterialType.SERVICE ? parseFloat(formData.selling_price) : undefined,
      cost_price: parseFloat(formData.cost_price) || 0,
      stock_quantity: formData.type === MaterialType.CONSUMABLE ? parseInt(formData.stock_quantity) : 0,
      order_limit: formData.type === MaterialType.CONSUMABLE ? parseInt(formData.order_limit) : 0,
      unit: formData.unit
    };

    setMaterials([newMaterial, ...materials]);
    setIsAddModalOpen(false);
    setFormData({
      name: '',
      type: MaterialType.SERVICE,
      selling_price: '',
      cost_price: '',
      stock_quantity: '',
      order_limit: '',
      unit: 'جلسة'
    });
  };

  return (
    <div className="space-y-6 text-right animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <h1 className="text-xl lg:text-2xl font-bold text-slate-800">مخزون العيادة والخدمات</h1>
        <div className="flex gap-2">
          <button 
            onClick={handleExport}
            className="flex-1 sm:flex-none px-4 py-2 border-2 border-slate-100 bg-white rounded-xl text-sm font-bold text-slate-600 hover:bg-slate-50 transition-all flex items-center justify-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
            تصدير CSV
          </button>
          <button 
            onClick={() => setIsAddModalOpen(true)}
            className="flex-1 sm:flex-none bg-indigo-600 text-white px-6 py-2 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100 flex items-center justify-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            إضافة عنصر
          </button>
        </div>
      </div>

      <div className="flex gap-4 border-b border-slate-200 overflow-x-auto no-scrollbar">
        {(['ALL', MaterialType.SERVICE, MaterialType.CONSUMABLE] as const).map(f => (
          <button 
            key={f}
            onClick={() => setFilter(f)}
            className={`px-4 py-2 text-sm font-bold transition-colors border-b-2 -mb-px whitespace-nowrap ${
              filter === f ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'
            }`}
          >
            {f === 'ALL' ? 'الكل' : f === MaterialType.SERVICE ? 'الخدمات' : 'المستلزمات'}
          </button>
        ))}
      </div>

      <div className="bg-white border border-slate-200 rounded-2xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-right min-w-[640px]">
            <thead className="bg-slate-50 border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">اسم العنصر</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">النوع</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-left">سعر البيع</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-left">التكلفة</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-center">المتوفر</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider">الحالة</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredItems.map(item => (
                <tr key={item.id} className="hover:bg-slate-50/50 transition-colors text-sm group">
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-800 group-hover:text-indigo-600 transition-colors">{item.name}</div>
                    <div className="text-[10px] text-slate-400 font-medium">معرف: {item.id}</div>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-lg uppercase tracking-wider border ${
                      item.type === MaterialType.SERVICE ? 'bg-indigo-50 text-indigo-600 border-indigo-100' : 'bg-amber-50 text-amber-600 border-amber-100'
                    }`}>
                      {item.type === MaterialType.SERVICE ? 'خدمة' : 'استهلاكي'}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-left font-bold text-slate-700">
                    {item.selling_price ? `$${item.selling_price.toFixed(2)}` : <span className="text-slate-200 font-normal">—</span>}
                  </td>
                  <td className="px-6 py-4 text-left font-bold text-slate-500">
                    ${item.cost_price.toFixed(2)}
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className={`font-bold ${item.type === MaterialType.SERVICE ? 'text-slate-300' : 'text-slate-700'}`}>
                      {item.type === MaterialType.SERVICE ? '∞' : `${item.stock_quantity} ${item.unit}`}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    {item.type === MaterialType.CONSUMABLE && item.stock_quantity <= item.order_limit ? (
                      <div className="flex items-center gap-1.5 text-red-600 text-[10px] font-bold uppercase bg-red-50 px-2 py-1 rounded-full w-fit">
                        <span className="w-1.5 h-1.5 bg-red-500 rounded-full animate-pulse" />
                        منخفض
                      </div>
                    ) : (
                      <div className="text-emerald-600 text-[10px] font-bold uppercase bg-emerald-50 px-2 py-1 rounded-full w-fit">نشط</div>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {filteredItems.length === 0 && (
          <div className="p-20 text-center flex flex-col items-center justify-center space-y-3">
             <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center">
