import ClinicAI from './components/ClinicAI';
import Login from './components/Login';
import AccountManagement from './components/AccountManagement';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const notificationRef = useRef<HTMLDivElement>(null);

  const [notifications, setNotifications] = useState<Notification[]>([
    { id: '1', title: 'تنبيه مخزون', message: 'وصل رصيد "إبر 1سم" إلى الحد الأدنى (15 قطعة)', time: 'منذ 5 دقائق', type: 'ALERT', read: false },
    { id: '2', title: 'موعد قادم', message: 'أليس فريمان لديها موعد فيلر بعد 30 دقيقة', time: 'منذ ساعة', type: 'INFO', read: false },
    { id: '3', title: 'تقرير مالي', message: 'تم استكمال تقرير الأرباح الأسبوعي بنجاح', time: 'منذ ساعتين', type: 'INFO', read: true },
  ]);

  const unreadCount = notifications.filter(n => !n.read).length;

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 1024) setIsSidebarOpen(false);
      else setIsSidebarOpen(true);
    };
    window.addEventListener('resize', handleResize);
    handleResize();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (notificationRef.current && !notificationRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  if (!currentUser) return <Login onLogin={(user) => setCurrentUser(user)} />;

  const userRole = currentUser.role;
  const tabs = [
    { id: 'dashboard', label: 'الرئيسية', icon: ICONS.Dashboard, roles: [UserRole.ADMIN, UserRole.DOCTOR, UserRole.RECEPTIONIST] },
    { id: 'patients', label: 'المرضى', icon: ICONS.Users, roles: [UserRole.ADMIN, UserRole.DOCTOR, UserRole.RECEPTIONIST] },
    { id: 'inventory', label: 'المخزون', icon: ICONS.Inventory, roles: [UserRole.ADMIN, UserRole.DOCTOR] },
    { id: 'accounting', label: 'المالية', icon: ICONS.Accounting, roles: [UserRole.ADMIN] },
    { id: 'ai', label: 'ذكاء العيادة', icon: ICONS.AI, roles: [UserRole.ADMIN, UserRole.DOCTOR] },
    { id: 'accounts', label: 'الموظفين', icon: ICONS.Shield, roles: [UserRole.ADMIN] },
  ];

  const filteredTabs = tabs.filter(tab => tab.roles.includes(userRole));

  const handleTabChange = (id: string) => {
    const canAccess = filteredTabs.some(t => t.id === id);
    if (canAccess) setActiveTab(id);
    setIsMobileMenuOpen(false);
  };

  return (
    <div className="min-h-screen flex overflow-hidden">
      {/* Sidebar - Modern Floating Style */}
      <aside className={`
        fixed inset-y-0 right-4 my-4 z-50 transition-all duration-500 transform
        lg:translate-x-0 lg:static lg:my-0 lg:right-0
        ${isMobileMenuOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}
        ${isSidebarOpen ? 'w-64' : 'w-20'}
        flex flex-col
      `}>
        <div className={`h-full bg-white/80 backdrop-blur-xl border border-white/40 rounded-[2.5rem] lg:rounded-none lg:border-none lg:bg-white shadow-2xl lg:shadow-none flex flex-col`}>
          <div className="p-8 flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-tr from-indigo-600 to-purple-500 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-indigo-200">
              <span className="text-xl font-black">G</span>
            </div>
            {isSidebarOpen && <span className="font-extrabold text-xl tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-slate-900 to-slate-500">دينتا جلو</span>}
          </div>

          <nav className="flex-1 px-4 space-y-2">
            {filteredTabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => handleTabChange(tab.id)}
                className={`w-full flex items-center gap-4 px-4 py-3.5 rounded-2xl transition-all duration-300 group ${
                  activeTab === tab.id 
                  ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-100 scale-[1.02]' 
                  : 'text-slate-500 hover:bg-slate-50 hover:text-indigo-600'
                }`}
              >
                <tab.icon className={`w-6 h-6 shrink-0 transition-transform group-hover:scale-110 ${activeTab === tab.id ? 'text-white' : 'text-slate-400 group-hover:text-indigo-500'}`} />
                {isSidebarOpen && <span className="font-bold text-sm tracking-wide">{tab.label}</span>}
              </button>
            ))}
          </nav>

          <div className="p-6 border-t border-slate-50">
            <div className={`flex items-center gap-3 p-2 rounded-2xl transition-colors ${isSidebarOpen ? 'hover:bg-slate-50' : ''}`}>
              <img src={`https://api.dicebear.com/7.x/avataaars/svg?seed=${currentUser.username}`} className="w-10 h-10 rounded-xl bg-indigo-50 border-2 border-white shadow-sm" alt="User" />
              {isSidebarOpen && (
                <div className="flex flex-col min-w-0">
                  <span className="text-sm font-bold text-slate-800 truncate">{currentUser.name}</span>
                  <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">{userRole}</span>
                </div>
              )}
            </div>
            <button 
              onClick={() => setCurrentUser(null)}
              className="mt-4 w-full flex items-center gap-4 px-4 py-3 text-rose-500 hover:bg-rose-50 rounded-2xl transition-all group"
            >
              <ICONS.Logout className="w-5 h-5 group-hover:-translate-x-1 transition-transform" />
              {isSidebarOpen && <span className="text-sm font-bold">تسجيل خروج</span>}
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0 h-screen overflow-hidden relative">
        <header className="h-20 flex items-center justify-between px-8 bg-white/40 backdrop-blur-md sticky top-0 z-40 border-b border-white/20">
          <div className="flex items-center gap-6">
            <button 
              onClick={() => isSidebarOpen ? setIsSidebarOpen(false) : setIsSidebarOpen(true)}
              className="p-2.5 bg-white shadow-sm border border-slate-100 rounded-xl text-slate-400 hover:text-indigo-600 hover:border-indigo-100 transition-all"
            >
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h7" /></svg>
            </button>
            <h2 className="text-xl font-black text-slate-800 tracking-tight hidden sm:block">
              {tabs.find(t => t.id === activeTab)?.label}
            </h2>
          </div>

          <div className="flex items-center gap-3">
            <div className="relative" ref={notificationRef}>
              <button 
                onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
                className="p-3 bg-white shadow-sm border border-slate-100 rounded-2xl text-slate-400 hover:text-indigo-600 transition-all relative group"
              >
                <ICONS.Bell className="w-6 h-6 group-hover:rotate-12 transition-transform" />
                {unreadCount > 0 && <span className="absolute top-2.5 right-2.5 w-2.5 h-2.5 bg-rose-500 rounded-full border-2 border-white animate-pulse"></span>}
              </button>
              {isNotificationsOpen && (
                <div className="absolute top-14 left-0 w-80 bg-white rounded-[2rem] shadow-2xl border border-slate-100 overflow-hidden z-[60] animate-in slide-in-from-top-4 duration-300">
                  <div className="p-5 border-b border-slate-50 bg-slate-50/50 flex items-center justify-between">
                    <span className="font-black text-sm text-slate-800">تنبيهات النظام</span>
                    {unreadCount > 0 && <span className="text-[10px] bg-indigo-600 text-white px-2 py-0.5 rounded-full font-bold">{unreadCount} جديد</span>}
                  </div>
                  <div className="max-h-[350px] overflow-y-auto p-2 space-y-1">
                    {notifications.map(n => (
                      <button key={n.id} className="w-full text-right p-4 hover:bg-slate-50 rounded-2xl transition-colors flex gap-4">
                        <div className={`w-2 h-2 rounded-full mt-1.5 shrink-0 ${n.type === 'ALERT' ? 'bg-rose-500' : 'bg-indigo-500'}`} />
                        <div className="flex-1 min-w-0">
                          <p className="font-bold text-xs text-slate-800 truncate">{n.title}</p>
                          <p className="text-[11px] text-slate-500 line-clamp-2 mt-0.5">{n.message}</p>
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>
            <div className="w-px h-8 bg-slate-200/50 mx-2" />
            <button className="hidden sm:flex items-center gap-3 bg-white px-4 py-2 border border-slate-100 rounded-2xl shadow-sm hover:shadow-md transition-all">
               <span className="w-2 h-2 bg-emerald-500 rounded-full"></span>
               <span className="text-xs font-bold text-slate-600">الخادم: نشط</span>
            </button>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-6 lg:p-10 custom-scrollbar">
          <div className="max-w-7xl mx-auto space-y-8">
            {renderContent()}
