/**
 * n8n Integration Service
 * 
 * هذا الملف مسؤول عن الربط المباشر بين التطبيق و n8n.
 * لضمان أفضل أداء، يفضل ضبط Webhooks من داخل لوحة تحكم Supabase 
 * (Database -> Webhooks) لتعمل بشكل تلقائي عند تغيير البيانات.
 */

// استبدل هذا الرابط برابط الـ Production Webhook من n8n
const N8N_WEBHOOK_URL = 'https://n8n.yourdomain.com/webhook/clinic-automation';

export type ClinicEventType = 'LOW_STOCK' | 'NEW_PATIENT' | 'APPOINTMENT_REMINDER' | 'DAILY_REPORT';

export const triggerN8nWorkflow = async (eventType: ClinicEventType, data: any) => {
  console.log(`[n8n] Triggering workflow for: ${eventType}`);

  try {
    const response = await fetch(N8N_WEBHOOK_URL, {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json',
        'X-Clinic-Event': eventType 
      },
      body: JSON.stringify({
        event: eventType,
        source: 'CLINIC_APP_FRONTEND',
        payload: data,
        timestamp: new Date().toISOString()
      })
    });

    if (!response.ok) {
      throw new Error(`n8n responded with status: ${response.status}`);
    }

    const result = await response.json();
    return { success: true, result };
  } catch (error) {
    console.error('[n8n] Integration Error:', error);
    return { 
      success: false, 
      error: error instanceof Error ? error.message : 'Unknown integration error' 
    };
  }
};

/**
 * نصيحة للمهندس:
 * لإرسال تنبيهات تلقائية عند نقص المخزون دون تدخل المستخدم:
 * 1. اذهب إلى Supabase Dashboard.
 * 2. اختر Database ثم Webhooks.
 * 3. فعل خيار Enable Webhooks.
 * 4. أنشئ Webhook جديد على جدول 'materials'.
 * 5. اختر حدث 'UPDATE'.
 * 6. ضع رابط n8n أعلاه كـ Destination.
 */

import React, { useState, useMemo } from 'react';
import { Material, MaterialType } from '../types';
import { triggerN8nWorkflow } from '../services/n8n';

const INITIAL_INVENTORY: Material[] = [
  { id: '1', name: 'حقن فيلر (شفايف)', type: MaterialType.SERVICE, selling_price: 350, cost_price: 120, stock_quantity: 0, order_limit: 0, unit: 'جلسة' },
  { id: '2', name: 'إبر 1سم', type: MaterialType.CONSUMABLE, selling_price: undefined, cost_price: 1.25, stock_quantity: 15, order_limit: 20, unit: 'قطعة' },
  { id: '3', name: 'حشوة أسنان ضوئية', type: MaterialType.CONSUMABLE, selling_price: undefined, cost_price: 45, stock_quantity: 42, order_limit: 10, unit: 'أنبوب' },
  { id: '4', name: 'جلسة تبييض', type: MaterialType.SERVICE, selling_price: 150, cost_price: 40, stock_quantity: 0, order_limit: 0, unit: 'جلسة' },
];

const Inventory: React.FC = () => {
  const [materials, setMaterials] = useState<Material[]>(INITIAL_INVENTORY);
  const [filter, setFilter] = useState<'ALL' | MaterialType>('ALL');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    type: MaterialType.SERVICE,
    selling_price: '',
    cost_price: '',
    stock_quantity: '',
    order_limit: '',
    unit: 'جلسة'
  });

  const filteredItems = useMemo(() => {
    return filter === 'ALL' 
      ? materials 
      : materials.filter(item => item.type === filter);
  }, [materials, filter]);

  const handleExport = () => {
    const headers = ['ID', 'Name', 'Type', 'Selling Price', 'Cost Price', 'Stock', 'Unit'];
    const rows = filteredItems.map(item => [
      item.id,
      item.name,
      item.type,
      item.selling_price || 'N/A',
      item.cost_price,
      item.stock_quantity,
      item.unit
    ]);

    const csvContent = "data:text/csv;charset=utf-8," 
      + [headers, ...rows].map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `inventory_export_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleAddMaterial = async (e: React.FormEvent) => {
    e.preventDefault();
    const newMaterial: Material = {
      id: (materials.length + 1).toString(),
      name: formData.name,
      type: formData.type,
      selling_price: formData.type === MaterialType.SERVICE ? parseFloat(formData.selling_price) : undefined,
      cost_price: parseFloat(formData.cost_price) || 0,
      stock_quantity: formData.type === MaterialType.CONSUMABLE ? parseInt(formData.stock_quantity) : 0,
      order_limit: formData.type === MaterialType.CONSUMABLE ? parseInt(formData.order_limit) : 0,
      unit: formData.unit
    };

    setMaterials([newMaterial, ...materials]);
    setIsAddModalOpen(false);

    // إرسال تنبيه إلى n8n عند إضافة مادة جديدة (اختياري - يفضل عملها عبر Supabase Webhooks)
    await triggerN8nWorkflow('LOW_STOCK', { 
      message: `تم إضافة عنصر جديد للمخزون: ${newMaterial.name}`,
      details: newMaterial 
    });

    setFormData({
      name: '', type: MaterialType.SERVICE, selling_price: '', cost_price: '',
