import { createClient } from '@supabase/supabase-js';

// Assume these are provided via the hosting environment (Vercel/Local)
const supabaseUrl = (process.env.SUPABASE_URL || 'https://your-project.supabase.co').trim();
const supabaseAnonKey = (process.env.SUPABASE_ANON_KEY || 'your-anon-key').trim();

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

import React, { useState, useEffect, useRef } from 'react';
import { User, UserRole, Notification } from './types';
import { ICONS } from './constants';
import { supabase } from './services/supabase';
import Dashboard from './components/Dashboard';
import PatientCRM from './components/PatientCRM';
import Inventory from './components/Inventory';
import Accounting from './components/Accounting';
import ClinicAI from './components/ClinicAI';
import Login from './components/Login';
import AccountManagement from './components/AccountManagement';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const notificationRef = useRef<HTMLDivElement>(null);

  const [notifications, setNotifications] = useState<Notification[]>([
    { id: '1', title: 'تنبيه مخزون', message: 'وصل رصيد "إبر 1سم" إلى الحد الأدنى (15 قطعة)', time: 'منذ 5 دقائق', type: 'ALERT', read: false },
    { id: '2', title: 'موعد قادم', message: 'أليس فريمان لديها موعد فيلر بعد 30 دقيقة', time: 'منذ ساعة', type: 'INFO', read: false },
  ]);

  const unreadCount = notifications.filter(n => !n.read).length;

  useEffect(() => {
    // Check initial session
    const checkUser = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
        setCurrentUser({
          id: session.user.id,
          username: session.user.email || '',
          name: session.user.user_metadata?.name || 'مستخدم العيادة',
          role: (session.user.user_metadata?.role as UserRole) || UserRole.RECEPTIONIST
        });
      }
      setIsAuthLoading(false);
    };

    checkUser();

    // Listen for auth changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        setCurrentUser({
          id: session.user.id,
          username: session.user.email || '',
          name: session.user.user_metadata?.name || 'مستخدم العيادة',
          role: (session.user.user_metadata?.role as UserRole) || UserRole.RECEPTIONIST
        });
      } else {
        setCurrentUser(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 1024) {
        setIsSidebarOpen(false);
      } else {
        setIsSidebarOpen(true);
      }
    };
    window.addEventListener('resize', handleResize);
    handleResize();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (notificationRef.current && !notificationRef.current.contains(event.target as Node)) {
        setIsNotificationsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  if (isAuthLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center gap-4">
        <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
        <p className="text-slate-500 font-bold animate-pulse">جاري التحقق من الهوية...</p>
      </div>
    );
  }

  if (!currentUser) {
    return <Login onLogin={(user) => setCurrentUser(user)} />;
  }

  const userRole = currentUser.role;

  const tabs = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: ICONS.Dashboard, roles: [UserRole.ADMIN, UserRole.DOCTOR, UserRole.RECEPTIONIST] },
    { id: 'patients', label: 'إدارة المرضى', icon: ICONS.Users, roles: [UserRole.ADMIN, UserRole.DOCTOR, UserRole.RECEPTIONIST] },
    { id: 'inventory', label: 'المخزون والخدمات', icon: ICONS.Inventory, roles: [UserRole.ADMIN, UserRole.DOCTOR] },
    { id: 'accounting', label: 'الحسابات والتقارير', icon: ICONS.Accounting, roles: [UserRole.ADMIN] },
    { id: 'ai', label: 'ذكاء العيادة (AI)', icon: ICONS.AI, roles: [UserRole.ADMIN, UserRole.DOCTOR] },
    { id: 'accounts', label: 'إدارة الموظفين', icon: ICONS.Shield, roles: [UserRole.ADMIN] },
  ];

  const filteredTabs = tabs.filter(tab => tab.roles.includes(userRole));

  const handleTabChange = (id: string) => {
    const canAccess = filteredTabs.some(t => t.id === id);
    if (canAccess) {
      setActiveTab(id);
    }
    setIsMobileMenuOpen(false);
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard onNavigate={handleTabChange} userRole={userRole} />;
      case 'patients': return <PatientCRM />;
      case 'inventory': return <Inventory />;
      case 'accounting': return <Accounting />;
      case 'ai': return <ClinicAI />;
      case 'accounts': return <AccountManagement />;
      default: return <Dashboard onNavigate={handleTabChange} userRole={userRole} />;
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setCurrentUser(null);
    setActiveTab('dashboard');
  };

  return (
    <div className="min-h-screen bg-slate-50 flex overflow-hidden" dir="rtl">
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-40 lg:hidden"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      <aside className={`
        fixed inset-y-0 right-0 z-50 bg-white border-l border-slate-200 transition-all duration-300 transform
        lg:translate-x-0 lg:static
        ${isMobileMenuOpen ? 'translate-x-0 w-72' : 'translate-x-full lg:translate-x-0'}
        ${isSidebarOpen ? 'lg:w-64' : 'lg:w-20'}
        flex flex-col shrink-0
      `}>
        <div className="p-6 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold">D</div>
            {(isSidebarOpen || isMobileMenuOpen) && <span className="font-bold text-xl tracking-tight">دينتا جلو</span>}
          </div>
        </div>

        <nav className="flex-1 px-4 py-4 space-y-1">
          {filteredTabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => handleTabChange(tab.id)}
              className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg transition-colors ${
                activeTab === tab.id 
                ? 'bg-indigo-50 text-indigo-700 font-medium' 
                : 'text-slate-600 hover:bg-slate-50'
              }`}
            >
              <tab.icon className="w-6 h-6 shrink-0" />
              {(isSidebarOpen || isMobileMenuOpen) && <span>{tab.label}</span>}
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-100 space-y-2">
           <div className="flex items-center gap-3 px-3 py-2">
             <div className="w-10 h-10 rounded-full bg-slate-200 flex items-center justify-center overflow-hidden border border-slate-100">
               <img src={`https://i.pravatar.cc/100?u=${currentUser.username}`} alt="User" />
             </div>
             {(isSidebarOpen || isMobileMenuOpen) && (
               <div className="flex flex-col text-right">
                 <span className="text-sm font-semibold truncate">{currentUser.name}</span>
                 <span className="text-[10px] font-bold text-indigo-500 uppercase tracking-wider">
                   {userRole === UserRole.ADMIN ? 'مدير النظام' : userRole === UserRole.DOCTOR ? 'طبيب' : 'استقبال'}
                 </span>
               </div>
             )}
           </div>

           <button 
             onClick={handleLogout}
             className="w-full flex items-center gap-3 px-3 py-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors"
           >
             <ICONS.Logout className="w-5 h-5 shrink-0" />
             {(isSidebarOpen || isMobileMenuOpen) && <span className="text-sm font-medium">تسجيل الخروج</span>}
           </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-16 bg-white border-b border-slate-200 px-4 lg:px-8 flex items-center justify-between sticky top-0 z-10">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => window.innerWidth < 1024 ? setIsMobileMenuOpen(true) : setIsSidebarOpen(!isSidebarOpen)}
              className="p-2 hover:bg-slate-50 rounded-lg text-slate-500"
            >
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" />
              </svg>
            </button>
            <h2 className="lg:hidden font-bold text-slate-800 truncate">
              {tabs.find(t => t.id === activeTab)?.label}
            </h2>
          </div>

          <div className="flex items-center gap-2 lg:gap-4">
            <div className="relative" ref={notificationRef}>
              <button 
                onClick={() => setIsNotificationsOpen(!isNotificationsOpen)}
                className="p-2 hover:bg-slate-50 rounded-full transition-colors relative"
              >
                <ICONS.Bell className={`w-6 h-6 transition-colors ${unreadCount > 0 ? 'text-indigo-600' : 'text-slate-400'}`} />
                {unreadCount > 0 && (
                  <span className="absolute top-1 right-1 w-4 h-4 bg-red-500 text-white text-[10px] flex items-center justify-center rounded-full border-2 border-white font-bold">
                    {unreadCount}
                  </span>
                )}
              </button>
            </div>

            <div className="hidden sm:block w-px h-6 bg-slate-200" />
            <div className="hidden sm:flex items-center gap-2">
              <span className="text-xs font-medium text-slate-500">حالة الربط السحابي:</span>
              <span className="w-2 h-2 bg-emerald-500 rounded-full" />
            </div>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-4 lg:p-8">
          <div className="max-w-7xl mx-auto">
            {renderContent()}
          </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Patient } from '../types';
import { supabase } from '../services/supabase';

interface PatientWithPhotos extends Patient {
  photos?: { id: string; url: string; type: 'BEFORE' | 'AFTER'; date: string }[];
}

const PatientCRM: React.FC = () => {
  const [patients, setPatients] = useState<PatientWithPhotos[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedPatient, setSelectedPatient] = useState<PatientWithPhotos | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [modalMode, setModalMode] = useState<'ADD' | 'EDIT' | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    name: '', age: '', phone1: '', phone2: '', address: '', medical: ''
  });

  useEffect(() => {
    fetchPatients();
  }, []);

  const fetchPatients = async () => {
    setIsLoading(true);
    const { data, error } = await supabase
      .from('patients')
      .select('*')
      .order('created_at', { ascending: false });

    if (!error && data) {
      setPatients(data);
    }
    setIsLoading(false);
  };

  const filteredPatients = useMemo(() => {
    return patients.filter(p => 
      p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      p.phones.some(phone => phone.includes(searchQuery))
    );
  }, [patients, searchQuery]);

  const openAddModal = () => {
    setModalMode('ADD');
    setFormData({ name: '', age: '', phone1: '', phone2: '', address: '', medical: '' });
  };

  const openEditModal = (patient: PatientWithPhotos) => {
    setModalMode('EDIT');
    setFormData({
      name: patient.name,
      age: patient.age.toString(),
      phone1: patient.phones[0] || '',
      phone2: patient.phones[1] || '',
      address: patient.address || '',
      medical: (patient.medical_history || []).join(', ')
    });
  };

  const handleFormSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const phones = [formData.phone1, formData.phone2].filter(p => p.trim() !== '');
    const medical = formData.medical.split(',').map(s => s.trim()).filter(s => s !== '');

    if (modalMode === 'ADD') {
      const { data, error } = await supabase
        .from('patients')
        .insert([{
          name: formData.name,
          age: parseInt(formData.age) || 0,
          phones: phones,
          address: formData.address,
          medical_history: medical
        }])
        .select();

      if (!error && data) {
        setPatients([data[0], ...patients]);
        setSelectedPatient(data[0]);
      }
    } else if (modalMode === 'EDIT' && selectedPatient) {
      const { error } = await supabase
        .from('patients')
        .update({
          name: formData.name,
          age: parseInt(formData.age) || 0,
          phones: phones,
          address: formData.address,
          medical_history: medical
        })
        .eq('id', selectedPatient.id);

      if (!error) {
        fetchPatients();
        setSelectedPatient({ ...selectedPatient, name: formData.name, age: parseInt(formData.age) || 0, phones, address: formData.address, medical_history: medical });
      }
    }

    setModalMode(null);
  };

  const handleAddPhoto = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!selectedPatient || !e.target.files?.length) return;
    alert("هذه الميزة تتطلب إعداد Supabase Storage (Bucket) - يتم رفع الصور حالياً للمعاينة فقط في الواجهة.");
  };

  const closeDetails = () => setSelectedPatient(null);

  return (
    <div className="h-full flex flex-col gap-4 lg:gap-6 text-right">
      <div className="flex items-center justify-between">
        <h1 className="text-xl lg:text-2xl font-bold text-slate-800">دليل المرضى</h1>
        <button 
          onClick={openAddModal}
          className="bg-indigo-600 text-white px-3 py-1.5 lg:px-4 lg:py-2 rounded-lg text-sm font-medium hover:bg-indigo-700 transition-colors shadow-md shadow-indigo-100"
        >
          + مريض جديد
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 flex-1 min-h-0">
        <div className={`lg:col-span-1 flex flex-col gap-4 ${selectedPatient ? 'hidden lg:flex' : 'flex'}`}>
          <div className="relative">
            <input 
              type="text" 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="ابحث بالاسم، رقم الهاتف..." 
              className="w-full pr-10 pl-4 py-3 bg-white border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none text-right text-sm text-black shadow-sm"
            />
            <svg className="w-5 h-5 absolute right-3 top-3.5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </div>

          <div className="bg-white border border-slate-200 rounded-2xl overflow-y-auto divide-y divide-slate-100 shadow-sm flex-1">
            {isLoading ? (
              <div className="p-10 flex justify-center"><div className="w-6 h-6 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></div></div>
            ) : filteredPatients.length > 0 ? (
              filteredPatients.map(p => (
                <button 
                  key={p.id}
                  onClick={() => setSelectedPatient(p)}
                  className={`w-full text-right p-4 hover:bg-slate-50 transition-colors ${selectedPatient?.id === p.id ? 'bg-indigo-50 border-r-4 border-indigo-600' : ''}`}
                >
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center font-bold text-indigo-600 shrink-0 border border-slate-200 text-lg">
                      {p.name.charAt(0)}
                    </div>
                    <div className="min-w-0 text-right">
                      <p className="font-semibold text-slate-800 truncate">{p.name}</p>
                      <p className="text-xs text-slate-500 truncate" dir="ltr">{p.phones[0]}</p>
                    </div>
                  </div>
                </button>
              ))
            ) : (
              <div className="p-8 text-center text-slate-400 text-sm italic">لا يوجد نتائج</div>
            )}
