import { createClient } from '@supabase/supabase-js';

/**
 * For Vercel/Vite deployments:
 * 1. SUPABASE_URL
 * 2. SUPABASE_ANON_KEY
 * Ensure these are set in Vercel Settings -> Environment Variables.
 */

const getEnv = (name: string): string => {
  // Check standard process.env (Vercel/Node)
  if (typeof process !== 'undefined' && process.env && process.env[name]) {
    return process.env[name] as string;
  }
  // Check Vite-specific meta.env
  // @ts-ignore
  if (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env[`VITE_${name}`]) {
    // @ts-ignore
    return import.meta.env[`VITE_${name}`];
  }
  return '';
};

const url = getEnv('SUPABASE_URL') || 'https://placeholder-project.supabase.co';
const key = getEnv('SUPABASE_ANON_KEY') || 'placeholder-anon-key';

if (url.includes('placeholder')) {
  console.warn("DentaGlow: Supabase credentials not found. Please set SUPABASE_URL and SUPABASE_ANON_KEY in Vercel.");
}

export const supabase = createClient(url, key);

import { GoogleGenAI } from "@google/genai";

const getGeminiKey = (): string => {
  if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
    return process.env.API_KEY;
  }
  // @ts-ignore
  if (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env.VITE_API_KEY) {
    // @ts-ignore
    return import.meta.env.VITE_API_KEY;
  }
  return '';
};

export const analyzeClinicData = async (prompt: string, dataContext: any) => {
  const apiKey = getGeminiKey();

  if (!apiKey) {
    throw new Error("DentaGlow: Gemini API_KEY is missing. Please add it to your Vercel Environment Variables.");
  }

  const ai = new GoogleGenAI({ apiKey });

  const systemInstruction = `
