/**
 * Environment Variable Strategy for DentaGlow Pro:
 * 1. Checks standard Node/Vercel process.env
 * 2. Checks Vite-style import.meta.env (for local dev)
 * 3. Falls back to a placeholder to prevent initialization crash
 */

const getEnvValue = (key: string): string => {
  // Check process.env (Vercel Production)
  if (typeof process !== 'undefined' && process.env && process.env[key]) {
    return process.env[key] as string;
  }

  // Check import.meta.env (Vite/Local Dev)
  // @ts-ignore
  if (typeof import.meta !== 'undefined' && import.meta.env) {
    // @ts-ignore
    const viteKey = `VITE_${key}`;
    // @ts-ignore
    if (import.meta.env[viteKey]) return import.meta.env[viteKey];
    // @ts-ignore
    if (import.meta.env[key]) return import.meta.env[key];
  }

  return '';
};

const supabaseUrl = getEnvValue('SUPABASE_URL');
const supabaseAnonKey = getEnvValue('SUPABASE_ANON_KEY');

