        thinkingConfig: { thinkingBudget: 32768 }
      },
    });

    // Directly access the .text property of the GenerateContentResponse.
    return response.text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import { createClient } from '@supabase/supabase-js';

/**
 * Robust Environment Variable Detection for Supabase.
 * In Vercel, these are injected into process.env.
 */
const getEnv = (key: string): string => {
  // @ts-ignore
  if (typeof process !== 'undefined' && process.env && process.env[key]) {
    // @ts-ignore
    return process.env[key];
  }
  // @ts-ignore
  if (typeof process !== 'undefined' && process.env && process.env[`NEXT_PUBLIC_${key}`]) {
    // @ts-ignore
    return process.env[`NEXT_PUBLIC_${key}`];
  }
  // @ts-ignore
  if (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env[`VITE_${key}`]) {
    return import.meta.env[`VITE_${key}`];
  }
  // @ts-ignore
  if (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env[key]) {
    return import.meta.env[key];
  }
  return '';
};

const supabaseUrl = getEnv('SUPABASE_URL');
