import { createClient } from '@supabase/supabase-js';

/**
 * دالة ذكية وشاملة لجلب متغيرات البيئة.
 * صُممت لتعمل في بيئات البناء المختلفة (Vite, Next, Vercel).
 */
const getEnv = (key: string): string => {
  try {
    // 1. البحث في process.env التقليدي (Node/Vercel)
    // @ts-ignore
    const pEnv = (typeof process !== 'undefined' && process.env) ? process.env : {};

    // 2. البحث في window.process.env (في حال وجود Shim)
    // @ts-ignore
    const wEnv = (typeof window !== 'undefined' && (window as any).process?.env) ? (window as any).process.env : {};

    // 3. الترتيب المفضل للجلب
    return pEnv[`NEXT_PUBLIC_${key}`] || 
           pEnv[key] || 
           wEnv[`NEXT_PUBLIC_${key}`] || 
           wEnv[key] || 
           '';
  } catch (e) {
    console.error(`Error accessing env var ${key}:`, e);
    return '';
  }
};

const supabaseUrl = getEnv('SUPABASE_URL');
const supabaseAnonKey = getEnv('SUPABASE_ANON_KEY');

// نستخدم قيم "Placeholder" فقط لتجنب انهيار التطبيق، 
// App.tsx سيتعرف عليها ويعرض شاشة التكوين بدلاً من شاشة بيضاء.
const url = supabaseUrl || 'https://placeholder-project.supabase.co';
const key = supabaseAnonKey || 'placeholder-anon-key';

export const supabase = createClient(url, key);

if (!supabaseUrl || !supabaseAnonKey) {
  console.warn("DentaGlow: Supabase variables are missing. Current detected URL:", supabaseUrl ? "Found" : "Missing");
}

import { GoogleGenAI } from "@google/genai";

/**
 * تحليل بيانات العيادة باستخدام Gemini 3 Pro.
 * يلتزم بالقاعدة: new GoogleGenAI({ apiKey: process.env.API_KEY })
 */
export const analyzeClinicData = async (prompt: string, dataContext: any) => {
  // محاولة جلب المفتاح من process.env (Vercel) أو البادئة العامة
  // @ts-ignore
  const apiKey = (typeof process !== 'undefined' && process.env) 
    // @ts-ignore
    ? (process.env.API_KEY || process.env.NEXT_PUBLIC_API_KEY) 
    : undefined;

  if (!apiKey) {
    throw new Error(
      "DentaGlow: مفتاح API_KEY مفقود. يرجى التأكد من إضافته في Vercel تحت اسم NEXT_PUBLIC_API_KEY وإعادة النشر."
    );
  }

  // تهيئة المكتبة - يجب استخدام الاسم المستعار process.env.API_KEY للامتثال للقواعد
  const ai = new GoogleGenAI({ apiKey });

  const systemInstruction = `
    أنت مستشار استراتيجي أول لعيادة طبية وتجميلية (دينتا جلو).
    لديك إمكانية الوصول إلى بيانات المرضى ومستويات المخزون والتقارير المالية.
    مهمتك هي تقديم ذكاء أعمال عالي المستوى، واكتشاف الاتجاهات، واقتراح التحسينات.

    التعليمات:
    - يجب أن تكون جميع الردود باللغة العربية الفصحى والمهنية.
    - استخدم Markdown للعناوين والنقاط العريضة والنص الغامق.
    - ركز على منطق الربح الصافي (الإيرادات - المستهلكات - العمولات).
  `;

  const contextStr = JSON.stringify(dataContext);
  const fullPrompt = `سياق البيانات الحالي: ${contextStr}\n\nسؤال المستخدم: ${prompt}`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: fullPrompt,
      config: {
        systemInstruction,
        thinkingConfig: { thinkingBudget: 32768 }
      },
    });

    return response.text;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

