/**
 * دالة ذكية وشاملة لجلب متغيرات البيئة لضمان عمل الاتصال المباشر.
 * تبحث في نطاقات process.env و window لضمان الوصول للقيم في المتصفح.
 */
const getEnv = (key: string): string => {
  try {
    // @ts-ignore
    const env = (typeof process !== 'undefined' && process.env) ? process.env : {};

    // الأولوية لمتغيرات Vercel العامة (Public)
    const value = env[`NEXT_PUBLIC_${key}`] || 
                  env[key] || 
                  // @ts-ignore
                  (typeof window !== 'undefined' && (window as any).process?.env?.[`NEXT_PUBLIC_${key}`]) ||
                  // @ts-ignore
                  (typeof window !== 'undefined' && (window as any).process?.env?.[key]) ||
                  '';

    return value.trim();
  } catch (e) {
    return '';
  }
};

const supabaseUrl = getEnv('SUPABASE_URL');
const supabaseAnonKey = getEnv('SUPABASE_ANON_KEY');

// التحقق من صحة الرابط قبل التهيئة
const isValidUrl = (url: string) => {
  try {
    new URL(url);
    return !url.includes('placeholder');
  } catch {
    return false;
  }
};

const url = isValidUrl(supabaseUrl) ? supabaseUrl : 'https://placeholder.supabase.co';
const key = (supabaseAnonKey && !supabaseAnonKey.includes('placeholder')) ? supabaseAnonKey : 'placeholder-key';

export const supabase = createClient(url, key);

// تصدير دوال مساعدة للتحقق من الاتصال
export const checkDbConnection = async () => {
  if (!isValidUrl(supabaseUrl)) return false;
  try {
    const { data, error } = await supabase.from('patients').select('id').limit(1);
    if (error) throw error;
    return true;
  } catch (err) {
    console.error("Database connection check failed:", err);
    return false;
  }
};

