import React, { useState, useMemo, useEffect } from 'react';
import { Material, MaterialType, UserRole } from '../types';
import { supabase } from '../services/supabase';

const Inventory: React.FC = () => {
  const [materials, setMaterials] = useState<Material[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [filter, setFilter] = useState<'ALL' | MaterialType>('ALL');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    type: MaterialType.SERVICE,
    selling_price: '',
    cost_price: '',
    stock_quantity: '0',
    order_limit: '10',
    unit: 'قطعة'
  });

  useEffect(() => {
    fetchInventory();
  }, []);

  const fetchInventory = async () => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('materials')
        .select('*')
        .order('name', { ascending: true });

      if (error) throw error;
      if (data) setMaterials(data);
    } catch (err: any) {
      console.error("Fetch error:", err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const filteredItems = useMemo(() => {
    return filter === 'ALL' 
      ? materials 
      : materials.filter(item => item.type === filter);
  }, [materials, filter]);

  const handleAddMaterial = async (e: React.FormEvent) => {
    e.preventDefault();

    // 1. التحقق من صحة البيانات الرقمية يدوياً قبل الإرسال
    const costPriceNum = parseFloat(formData.cost_price);
    const sellingPriceNum = parseFloat(formData.selling_price);
    const stockQtyNum = parseInt(formData.stock_quantity);
    const orderLimitNum = parseInt(formData.order_limit);

    if (isNaN(costPriceNum)) {
      alert("يرجى إدخال تكلفة صحيحة (أرقام فقط)");
      return;
    }

    if (formData.type === MaterialType.SERVICE && isNaN(sellingPriceNum)) {
      alert("بالنسبة للخدمات، يجب تحديد سعر البيع للمريض");
      return;
    }

    setIsSubmitting(true);

    try {
      // 2. بناء الكائن (Payload) مع ضمان عدم وجود قيم NaN
      const payload: any = {
        name: formData.name.trim(),
        type: formData.type,
        cost_price: costPriceNum,
        unit: formData.type === MaterialType.CONSUMABLE ? formData.unit : 'جلسة',
        stock_quantity: formData.type === MaterialType.CONSUMABLE ? (isNaN(stockQtyNum) ? 0 : stockQtyNum) : 0,
        order_limit: formData.type === MaterialType.CONSUMABLE ? (isNaN(orderLimitNum) ? 10 : orderLimitNum) : 0,
      };

      // إذا كان خدمة نضيف سعر البيع، إذا كان مادة نتركه فارغاً
      if (formData.type === MaterialType.SERVICE) {
        payload.selling_price = sellingPriceNum;
      } else {
        payload.selling_price = null;
      }

      // 3. محاولة الإرسال لـ Supabase
      const { data, error } = await supabase
        .from('materials')
        .insert([payload])
        .select();

      if (error) {
        // في حال وجود RLS Policy تمنع الإضافة
        if (error.code === '42501') {
          throw new Error("عذراً، لا تملك صلاحية إضافة عناصر. يجب أن يكون حسابك بصلاحية 'ADMIN'.");
        }
