import React, { useState, useEffect } from 'react';
import { User, UserRole, Notification } from './types';
import { ICONS } from './constants';
import { supabase, checkDbConnection } from './services/supabase';
import Dashboard from './components/Dashboard';
import PatientCRM from './components/PatientCRM';
import Inventory from './components/Inventory';
import Accounting from './components/Accounting';
import ClinicAI from './components/ClinicAI';
import Login from './components/Login';
import AccountManagement from './components/AccountManagement';
import Appointments from './components/Appointments';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [connectionError, setConnectionError] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [notifications] = useState<Notification[]>([]);

  useEffect(() => {
    const initApp = async () => {
      try {
        const isConnected = await checkDbConnection();
        if (!isConnected) {
          setConnectionError(true);
        }

        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
          setCurrentUser({
            id: session.user.id,
            username: session.user.email || '',
            name: session.user.user_metadata?.name || 'مستخدم العيادة',
            role: (session.user.user_metadata?.role as UserRole) || UserRole.RECEPTIONIST
          });
        }
      } catch (err) {
        console.error("App startup failed:", err);
      } finally {
        setIsAuthLoading(false);
      }
    };

    initApp();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        setCurrentUser({
          id: session.user.id,
          username: session.user.email || '',
          name: session.user.user_metadata?.name || 'مستخدم العيادة',
          role: (session.user.user_metadata?.role as UserRole) || UserRole.RECEPTIONIST
        });
      } else {
        setCurrentUser(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setCurrentUser(null);
  };

  if (isAuthLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center gap-6">
        <div className="relative">
          <div className="w-16 h-16 border-4 border-slate-100 rounded-full"></div>
          <div className="absolute top-0 w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
        </div>
        <div className="text-center space-y-2">
          <p className="text-slate-800 font-bold text-lg">DentaGlow Pro</p>
          <p className="text-slate-400 text-sm animate-pulse">جاري التحقق من الاتصال بالسحاب...</p>
        </div>
      </div>
    );
  }

  if (connectionError && !currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
        <div className="max-w-md w-full bg-white p-8 rounded-3xl shadow-xl text-center space-y-4">
          <div className="w-16 h-16 bg-rose-50 text-rose-600 rounded-full flex items-center justify-center mx-auto">
            <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
          </div>
          <h2 className="text-xl font-bold text-slate-800">خطأ في الاتصال بالسحاب</h2>
          <p className="text-slate-500 text-sm leading-relaxed">
            تعذر الاتصال بقاعدة بيانات Supabase. يرجى التأكد من إعدادات الاتصال.
          </p>
          <button onClick={() => window.location.reload()} className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold hover:bg-indigo-700 transition-colors">إعادة المحاولة</button>
        </div>
      </div>
    );
  }

  if (!currentUser) {
    return <Login onLogin={(user) => setCurrentUser(user)} />;
  }

  const userRole = currentUser.role;

  const tabs = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: ICONS.Dashboard, roles: [UserRole.ADMIN, UserRole.DOCTOR, UserRole.RECEPTIONIST] },
    { id: 'appointments', label: 'المواعيد', icon: ICONS.Calendar, roles: [UserRole.ADMIN, UserRole.DOCTOR, UserRole.RECEPTIONIST] },
    { id: 'patients', label: 'إدارة المرضى', icon: ICONS.Users, roles: [UserRole.ADMIN, UserRole.DOCTOR, UserRole.RECEPTIONIST] },
    { id: 'inventory', label: 'المخزون', icon: ICONS.Inventory, roles: [UserRole.ADMIN, UserRole.RECEPTIONIST] },
    { id: 'accounting', label: 'المحاسبة', icon: ICONS.Accounting, roles: [UserRole.ADMIN] },
    { id: 'ai', label: 'الذكاء الاصطناعي', icon: ICONS.AI, roles: [UserRole.ADMIN, UserRole.DOCTOR] },
    { id: 'accounts', label: 'الموظفين', icon: ICONS.Shield, roles: [UserRole.ADMIN] },
  ];

  const filteredTabs = tabs.filter(tab => tab.roles.includes(userRole));

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans" dir="rtl">
      <aside className={`bg-white border-l border-slate-200 transition-all duration-300 ${isSidebarOpen ? 'w-64' : 'w-20'} hidden lg:flex flex-col`}>
        <div className="p-6 flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shrink-0">
            <span className="text-white font-black text-xl">D</span>
          </div>
          {isSidebarOpen && <span className="font-black text-slate-800 text-xl tracking-tight">DentaGlow</span>}
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4 overflow-y-auto no-scrollbar">
          {filteredTabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all ${
                activeTab === tab.id ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50 hover:text-slate-600'
              }`}
            >
              <tab.icon className="w-6 h-6 shrink-0" />
              {isSidebarOpen && <span className="font-bold text-sm">{tab.label}</span>}
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-100">
           <button 
             onClick={handleLogout}
             className="w-full flex items-center gap-3 p-3 text-rose-400 hover:bg-rose-50 hover:text-rose-600 rounded-xl transition-all"
           >
             <ICONS.Logout className="w-6 h-6 shrink-0" />
             {isSidebarOpen && <span className="font-bold text-sm">تسجيل الخروج</span>}
           </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 lg:px-8 shrink-0">
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="hidden lg:block text-slate-400 hover:text-slate-600">
             <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
          </button>

          <div className="flex items-center gap-4">
            <div className="text-left">
              <p className="text-[10px] font-bold text-slate-400 uppercase leading-none mb-1">{currentUser.role}</p>
              <p className="text-sm font-black text-slate-800 leading-none">{currentUser.name}</p>
            </div>
            <div className="w-10 h-10 rounded-full bg-slate-100 border-2 border-white shadow-sm flex items-center justify-center font-bold text-indigo-600 shrink-0">
              {currentUser.name.charAt(0)}
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8">
          {activeTab === 'dashboard' && <Dashboard onNavigate={setActiveTab} userRole={userRole} />}
          {activeTab === 'appointments' && <Appointments />}
          {activeTab === 'patients' && <PatientCRM />}
          {activeTab === 'inventory' && <Inventory />}
          {activeTab === 'accounting' && <Accounting />}
          {activeTab === 'ai' && <ClinicAI />}
          {activeTab === 'accounts' && <AccountManagement />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { Appointment, AppointmentStatus, Patient } from '../types';
import { supabase } from '../services/supabase';

const Appointments: React.FC = () => {
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [patients, setPatients] = useState<Patient[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Filters
  const [dateFilter, setDateFilter] = useState(new Date().toISOString().split('T')[0]);
  const [statusFilter, setStatusFilter] = useState<string>('ALL');

  // Form State
  const [formData, setFormData] = useState({
    patient_id: '',
    appointment_date: '',
    appointment_time: '10:00',
    notes: '',
    status: AppointmentStatus.PENDING
  });

  const [searchPatientQuery, setSearchPatientQuery] = useState('');

  useEffect(() => {
    fetchAppointments();
    fetchPatients();
  }, [dateFilter]);

  const fetchPatients = async () => {
    const { data } = await supabase.from('patients').select('id, name').order('name');
    if (data) setPatients(data);
  };

  const fetchAppointments = async () => {
    setIsLoading(true);
    try {
      // Fetch appointments for the selected day
      const { data, error } = await supabase
        .from('appointments')
        .select(`
          *,
          patients ( name )
        `)
        .gte('appointment_date', `${dateFilter}T00:00:00`)
        .lte('appointment_date', `${dateFilter}T23:59:59`)
        .order('appointment_date', { ascending: true });

      if (error) throw error;

      const mapped = data?.map(app => ({
        ...app,
        patient_name: app.patients?.name || 'مريض غير معروف'
      })) || [];

      setAppointments(mapped);
    } catch (err) {
      console.error("Error fetching appointments:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const filteredAppointments = useMemo(() => {
    if (statusFilter === 'ALL') return appointments;
    return appointments.filter(app => app.status === statusFilter);
  }, [appointments, statusFilter]);

  const handleAddAppointment = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const fullDateTime = `${formData.appointment_date}T${formData.appointment_time}:00`;

      const { error } = await supabase
        .from('appointments')
        .insert([{
          patient_id: formData.patient_id,
          appointment_date: fullDateTime,
          status: formData.status,
          notes: formData.notes
        }]);

      if (error) throw error;

      await fetchAppointments();
      setIsModalOpen(false);
      setFormData({
        patient_id: '',
        appointment_date: '',
        appointment_time: '10:00',
        notes: '',
        status: AppointmentStatus.PENDING
      });
    } catch (err: any) {
      alert("خطأ في حفظ الموعد: " + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const updateStatus = async (id: string, newStatus: AppointmentStatus) => {
    try {
      const { error } = await supabase
        .from('appointments')
        .update({ status: newStatus })
        .eq('id', id);

      if (error) throw error;
      fetchAppointments();
    } catch (err: any) {
      alert("خطأ في تحديث الحالة: " + err.message);
    }
  };

  const filteredPatientList = patients.filter(p => 
    p.name.toLowerCase().includes(searchPatientQuery.toLowerCase())
  );

  return (
    <div className="space-y-6 text-right animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-800">إدارة مواعيد العيادة</h1>
          <p className="text-slate-500 text-sm font-medium">جدولة الجلسات والمتابعة اليومية.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-indigo-600 text-white px-6 py-3 rounded-2xl font-bold text-sm hover:bg-indigo-700 shadow-lg shadow-indigo-100 transition-all flex items-center justify-center gap-2"
        >
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          حجز موعد جديد
        </button>
      </div>

      <div className="bg-white p-4 rounded-3xl border border-slate-100 shadow-sm flex flex-wrap gap-4 items-center">
        <div className="flex items-center gap-2">
           <span className="text-xs font-bold text-slate-400">التاريخ:</span>
           <input 
             type="date" 
             value={dateFilter}
             onChange={(e) => setDateFilter(e.target.value)}
             className="bg-slate-50 border-none rounded-xl px-4 py-2 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
           />
        </div>
        <div className="flex items-center gap-2">
           <span className="text-xs font-bold text-slate-400">الحالة:</span>
           <select 
             value={statusFilter}
             onChange={(e) => setStatusFilter(e.target.value)}
             className="bg-slate-50 border-none rounded-xl px-4 py-2 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
           >
             <option value="ALL">الكل</option>
             <option value={AppointmentStatus.PENDING}>قيد الانتظار</option>
             <option value={AppointmentStatus.CONFIRMED}>مؤكد</option>
             <option value={AppointmentStatus.COMPLETED}>مكتمل</option>
             <option value={AppointmentStatus.CANCELLED}>ملغى</option>
           </select>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {isLoading ? (
          <div className="p-20 flex flex-col items-center justify-center gap-4">
             <div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
             <p className="text-slate-400 font-bold">جاري تحميل المواعيد...</p>
          </div>
        ) : filteredAppointments.length > 0 ? (
          filteredAppointments.map((app) => (
            <div key={app.id} className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm hover:shadow-md transition-all flex flex-col md:flex-row md:items-center justify-between gap-4 group">
              <div className="flex items-center gap-4">
                <div className="w-14 h-14 rounded-2xl bg-slate-50 flex flex-col items-center justify-center border border-slate-100 shrink-0">
                  <span className="text-indigo-600 font-black text-sm">{new Date(app.appointment_date).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}</span>
                </div>
                <div>
                  <h3 className="font-black text-slate-800 group-hover:text-indigo-600 transition-colors">{app.patient_name}</h3>
                  <p className="text-xs text-slate-400 font-medium">{app.notes || 'بدون ملاحظات إضافية'}</p>
                </div>
              </div>

              <div className="flex items-center gap-3">
                <select 
                  value={app.status}
                  onChange={(e) => updateStatus(app.id, e.target.value as AppointmentStatus)}
                  className={`text-[10px] font-black px-3 py-1.5 rounded-xl border outline-none transition-all ${
                    app.status === AppointmentStatus.PENDING ? 'bg-amber-50 text-amber-600 border-amber-100' :
                    app.status === AppointmentStatus.CONFIRMED ? 'bg-indigo-50 text-indigo-600 border-indigo-100' :
                    app.status === AppointmentStatus.COMPLETED ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
                    'bg-rose-50 text-rose-600 border-rose-100'
                  }`}
                >
                  <option value={AppointmentStatus.PENDING}>قيد الانتظار</option>
                  <option value={AppointmentStatus.CONFIRMED}>مؤكد</option>
                  <option value={AppointmentStatus.COMPLETED}>مكتمل</option>
                  <option value={AppointmentStatus.CANCELLED}>ملغى</option>
                </select>
              </div>
            </div>
          ))
        ) : (
          <div className="p-20 text-center bg-white rounded-3xl border-2 border-dashed border-slate-100">
            <p className="text-slate-400 font-medium italic">لا توجد مواعيد مسجلة لهذا اليوم.</p>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] p-8 max-w-lg w-full shadow-2xl animate-in zoom-in-95 text-right overflow-y-auto max-h-[90vh]">
            <h2 className="text-2xl font-black text-slate-800 mb-6">حجز موعد جديد</h2>
            <form onSubmit={handleAddAppointment} className="space-y-5">

              <div>
                <label className="block text-xs font-black text-slate-400 mb-1.5 uppercase tracking-widest">اختر المريض</label>
                <div className="relative">
                  <input 
                    placeholder="ابحث عن اسم المريض..."
                    className="w-full px-5 py-3.5 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold mb-2"
                    value={searchPatientQuery}
                    onChange={(e) => setSearchPatientQuery(e.target.value)}
                  />
                  <select 
                    required
                    size={4}
                    value={formData.patient_id}
                    onChange={(e) => setFormData({...formData, patient_id: e.target.value})}
                    className="w-full px-5 py-2 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold bg-white"
                  >
                    {filteredPatientList.map(p => (
                      <option key={p.id} value={p.id}>{p.name}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-1.5 uppercase tracking-widest">التاريخ</label>
                  <input 
                    type="date" 
                    required
                    value={formData.appointment_date}
                    onChange={(e) => setFormData({...formData, appointment_date: e.target.value})}
                    className="w-full px-5 py-3.5 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold"
                  />
                </div>
                <div>
                  <label className="block text-xs font-black text-slate-400 mb-1.5 uppercase tracking-widest">الوقت</label>
                  <input 
                    type="time" 
                    required
                    value={formData.appointment_time}
                    onChange={(e) => setFormData({...formData, appointment_time: e.target.value})}
                    className="w-full px-5 py-3.5 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-black text-slate-400 mb-1.5 uppercase tracking-widest">ملاحظات (اختياري)</label>
                <textarea 
                  rows={3}
                  value={formData.notes}
                  onChange={(e) => setFormData({...formData, notes: e.target.value})}
                  className="w-full px-5 py-3.5 rounded-2xl border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500 font-bold"
                />
              </div>

              <div className="pt-4 flex flex-col gap-3">
                <button 
                  type="submit" 
                  disabled={isSubmitting || !formData.patient_id}
                  className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black text-sm hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 flex items-center justify-center gap-2 disabled:opacity-50"
                >
                  {isSubmitting ? 'جاري الحفظ...' : 'تأكيد حجز الموعد'}
                </button>
                <button 
                  type="button" 
                  onClick={() => setIsModalOpen(false)} 
                  className="w-full text-slate-400 font-bold py-2 hover:text-slate-600 transition-colors"
                >
                  إلغاء
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Appointments;

import React, { useState, useEffect } from 'react';
import { User, UserRole, Notification } from './types';
import { ICONS } from './constants';
import { supabase, checkDbConnection } from './services/supabase';
import Dashboard from './components/Dashboard';
import PatientCRM from './components/PatientCRM';
import Inventory from './components/Inventory';
import Accounting from './components/Accounting';
import ClinicAI from './components/ClinicAI';
import Login from './components/Login';
import AccountManagement from './components/AccountManagement';
import Appointments from './components/Appointments';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [connectionError, setConnectionError] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [notifications] = useState<Notification[]>([]);

  useEffect(() => {
    const initApp = async () => {
      try {
        const isConnected = await checkDbConnection();
        if (!isConnected) {
          setConnectionError(true);
        }

        const { data: { session } } = await supabase.auth.getSession();
        if (session?.user) {
          setCurrentUser({
            id: session.user.id,
            username: session.user.email || '',
            name: session.user.user_metadata?.name || 'مستخدم العيادة',
            role: (session.user.user_metadata?.role as UserRole) || UserRole.RECEPTIONIST
          });
        }
      } catch (err) {
        console.error("App startup failed:", err);
      } finally {
        setIsAuthLoading(false);
      }
    };

    initApp();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        setCurrentUser({
          id: session.user.id,
          username: session.user.email || '',
          name: session.user.user_metadata?.name || 'مستخدم العيادة',
          role: (session.user.user_metadata?.role as UserRole) || UserRole.RECEPTIONIST
        });
      } else {
        setCurrentUser(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setCurrentUser(null);
  };

  if (isAuthLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center gap-6">
        <div className="relative">
          <div className="w-16 h-16 border-4 border-slate-100 rounded-full"></div>
          <div className="absolute top-0 w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
        </div>
        <div className="text-center space-y-2">
          <p className="text-slate-800 font-bold text-lg">DentaGlow Pro</p>
          <p className="text-slate-400 text-sm animate-pulse">جاري التحقق من الاتصال بالسحاب...</p>
        </div>
      </div>
    );
  }

  if (connectionError && !currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
        <div className="max-w-md w-full bg-white p-8 rounded-3xl shadow-xl text-center space-y-4">
          <div className="w-16 h-16 bg-rose-50 text-rose-600 rounded-full flex items-center justify-center mx-auto">
            <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
          </div>
          <h2 className="text-xl font-bold text-slate-800">خطأ في الاتصال بالسحاب</h2>
          <p className="text-slate-500 text-sm leading-relaxed">
            تعذر الاتصال بقاعدة بيانات Supabase. يرجى التأكد من إعدادات الاتصال.
          </p>
          <button onClick={() => window.location.reload()} className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold hover:bg-indigo-700 transition-colors">إعادة المحاولة</button>
        </div>
      </div>
    );
  }

  if (!currentUser) {
    return <Login onLogin={(user) => setCurrentUser(user)} />;
  }

  const userRole = currentUser.role;

  const tabs = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: ICONS.Dashboard, roles: [UserRole.ADMIN, UserRole.DOCTOR, UserRole.RECEPTIONIST] },
    { id: 'appointments', label: 'المواعيد', icon: ICONS.Calendar, roles: [UserRole.ADMIN, UserRole.DOCTOR, UserRole.RECEPTIONIST] },
    { id: 'patients', label: 'إدارة المرضى', icon: ICONS.Users, roles: [UserRole.ADMIN, UserRole.DOCTOR, UserRole.RECEPTIONIST] },
    { id: 'inventory', label: 'المخزون', icon: ICONS.Inventory, roles: [UserRole.ADMIN, UserRole.RECEPTIONIST] },
    { id: 'accounting', label: 'المحاسبة', icon: ICONS.Accounting, roles: [UserRole.ADMIN] },
    { id: 'ai', label: 'الذكاء الاصطناعي', icon: ICONS.AI, roles: [UserRole.ADMIN, UserRole.DOCTOR] },
    { id: 'accounts', label: 'الموظفين', icon: ICONS.Shield, roles: [UserRole.ADMIN] },
  ];

  const filteredTabs = tabs.filter(tab => tab.roles.includes(userRole));

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans" dir="rtl">
      <aside className={`bg-white border-l border-slate-200 transition-all duration-300 ${isSidebarOpen ? 'w-64' : 'w-20'} hidden lg:flex flex-col`}>
        <div className="p-6 flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shrink-0">
            <span className="text-white font-black text-xl">D</span>
          </div>
          {isSidebarOpen && <span className="font-black text-slate-800 text-xl tracking-tight">DentaGlow</span>}
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4 overflow-y-auto no-scrollbar">
          {filteredTabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`w-full flex items-center gap-3 p-3 rounded-xl transition-all ${
                activeTab === tab.id ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50 hover:text-slate-600'
              }`}
            >
              <tab.icon className="w-6 h-6 shrink-0" />
              {isSidebarOpen && <span className="font-bold text-sm">{tab.label}</span>}
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-100">
           <button 
             onClick={handleLogout}
             className="w-full flex items-center gap-3 p-3 text-rose-400 hover:bg-rose-50 hover:text-rose-600 rounded-xl transition-all"
           >
             <ICONS.Logout className="w-6 h-6 shrink-0" />
             {isSidebarOpen && <span className="font-bold text-sm">تسجيل الخروج</span>}
           </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 lg:px-8 shrink-0">
          <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="hidden lg:block text-slate-400 hover:text-slate-600">
             <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
          </button>

          <div className="flex items-center gap-4">
            <div className="text-left">
              <p className="text-[10px] font-bold text-slate-400 uppercase leading-none mb-1">{currentUser.role}</p>
              <p className="text-sm font-black text-slate-800 leading-none">{currentUser.name}</p>
            </div>
            <div className="w-10 h-10 rounded-full bg-slate-100 border-2 border-white shadow-sm flex items-center justify-center font-bold text-indigo-600 shrink-0">
              {currentUser.name.charAt(0)}
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8">
          {activeTab === 'dashboard' && <Dashboard onNavigate={setActiveTab} userRole={userRole} />}
          {activeTab === 'appointments' && <Appointments currentUser={currentUser} />}
          {activeTab === 'patients' && <PatientCRM />}
          {activeTab === 'inventory' && <Inventory />}
          {activeTab === 'accounting' && <Accounting />}
          {activeTab === 'ai' && <ClinicAI />}
          {activeTab === 'accounts' && <AccountManagement />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { Appointment, AppointmentStatus, Patient, User } from '../types';
import { supabase } from '../services/supabase';

interface AppointmentsProps {
  currentUser?: User | null;
}

const Appointments: React.FC<AppointmentsProps> = ({ currentUser }) => {
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [patients, setPatients] = useState<Patient[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Filters
  const [dateFilter, setDateFilter] = useState(new Date().toISOString().split('T')[0]);
  const [statusFilter, setStatusFilter] = useState<string>('ALL');

  // Form State
  const [formData, setFormData] = useState({
    patient_id: '',
    appointment_date: dateFilter,
    appointment_time: '10:00',
    notes: '',
    status: AppointmentStatus.PENDING
  });

  const [searchPatientQuery, setSearchPatientQuery] = useState('');

  useEffect(() => {
    fetchAppointments();
    fetchPatients();
  }, [dateFilter]);

  // Update form date when filter changes to keep consistency
  useEffect(() => {
    setFormData(prev => ({ ...prev, appointment_date: dateFilter }));
  }, [dateFilter]);

  const fetchPatients = async () => {
    const { data } = await supabase.from('patients').select('id, name').order('name');
    if (data) setPatients(data);
  };

  const fetchAppointments = async () => {
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('appointments')
        .select(`
          *,
          patients ( name )
        `)
        .gte('appointment_date', `${dateFilter}T00:00:00`)
        .lte('appointment_date', `${dateFilter}T23:59:59`)
        .order('appointment_date', { ascending: true });

      if (error) throw error;

      const mapped = data?.map(app => ({
        ...app,
        patient_name: app.patients?.name || 'مريض غير معروف'
      })) || [];

      setAppointments(mapped);
    } catch (err) {
      console.error("Error fetching appointments:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const filteredAppointments = useMemo(() => {
    if (statusFilter === 'ALL') return appointments;
    return appointments.filter(app => app.status === statusFilter);
  }, [appointments, statusFilter]);

  const handleAddAppointment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.patient_id) {
      alert("يرجى اختيار مريض من القائمة أولاً.");
      return;
    }

    setIsSubmitting(true);

    try {
      const fullDateTime = `${formData.appointment_date}T${formData.appointment_time}:00`;

      const { data, error } = await supabase
        .from('appointments')
        .insert([{
          patient_id: formData.patient_id,
          doctor_id: currentUser?.id, // تأكد من إرسال معرف الطبيب
          appointment_date: fullDateTime,
          status: formData.status,
          notes: formData.notes.trim()
        }])
        .select();

      if (error) throw error;

      await fetchAppointments();
      setIsModalOpen(false);
      setFormData({
        patient_id: '',
        appointment_date: dateFilter,
        appointment_time: '10:00',
        notes: '',
        status: AppointmentStatus.PENDING
      });
      setSearchPatientQuery('');
    } catch (err: any) {
      console.error("Save Error:", err);
      alert("خطأ في حفظ الموعد: " + (err.message || "حدث خطأ غير معروف"));
    } finally {
      setIsSubmitting(false);
    }
  };

  const updateStatus = async (id: string, newStatus: AppointmentStatus) => {
    try {
      const { error } = await supabase
        .from('appointments')
        .update({ status: newStatus })
        .eq('id', id);

      if (error) throw error;
      fetchAppointments();
    } catch (err: any) {
      alert("خطأ في تحديث الحالة: " + err.message);
    }
  };

  const filteredPatientList = patients.filter(p => 
    p.name.toLowerCase().includes(searchPatientQuery.toLowerCase())
  );

  return (
    <div className="space-y-6 text-right animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
